// ICU79.1 oracle only: validates CLDR49 parser AST roundtrips. No production CE data exported.
#define SOUNIO_CLDR_NO_MAIN
#include "cldr_generate.cpp"
#include <unicode/ucol.h>
#include <unicode/ustring.h>
#include <iomanip>
struct Rune{std::uint32_t cp;bool escaped;};
std::vector<Rune> decode(const std::string&s){
 std::vector<Rune> out;std::size_t i=0;while(i<s.size()){auto c=static_cast<unsigned char>(s[i++]);std::uint32_t cp=0;bool escaped=false;
  if(c=='\\'){escaped=true;if(i==s.size())bad("escape EOF");c=static_cast<unsigned char>(s[i++]);if(c=='u'||c=='U'){int n=c=='u'?4:8;for(int j=0;j<n;++j){if(i==s.size())bad("hex EOF");auto h=static_cast<unsigned char>(s[i++]);int v=h>='0'&&h<='9'?h-'0':h>='a'&&h<='f'?h-'a'+10:h>='A'&&h<='F'?h-'A'+10:-1;if(v<0)bad("hex");cp=(cp<<4)|v;}}else cp=c;
  }else if(c<128)cp=c;else{int n=c>=194&&c<=223?1:c>=224&&c<=239?2:c>=240&&c<=244?3:-1;if(n<0)bad("UTF8 lead");cp=c&((1U<<(6-n))-1);for(int j=0;j<n;++j){if(i==s.size())bad("UTF8 short");auto b=static_cast<unsigned char>(s[i++]);if((b&192)!=128)bad("UTF8 continuation");cp=(cp<<6)|(b&63);}if(cp<(n==1?128U:n==2?2048U:65536U))bad("UTF8 overlong");}
  if(cp>0x10FFFF||(cp>=0xD800&&cp<=0xDFFF))bad("non-scalar rule code point");out.push_back({cp,escaped});
 }return out;
}
std::string utf8_cp(std::uint32_t cp){std::string s;if(cp<=127)s.push_back(cp);else if(cp<=2047){s.push_back(192+(cp>>6));s.push_back(128+(cp&63));}else if(cp<=65535){s.push_back(224+(cp>>12));s.push_back(128+((cp>>6)&63));s.push_back(128+(cp&63));}else{s.push_back(240+(cp>>18));s.push_back(128+((cp>>12)&63));s.push_back(128+((cp>>6)&63));s.push_back(128+(cp&63));}return s;}
std::string encoded(const std::string&s,bool starred=false){std::string out;for(auto r:decode(s)){if(starred&&r.cp==45&&!r.escaped){out+='-';continue;}bool syntax=(r.cp>=33&&r.cp<=47)||(r.cp>=58&&r.cp<=64)||(r.cp>=91&&r.cp<=96)||(r.cp>=123&&r.cp<=126);bool white=(r.cp>=9&&r.cp<=13)||r.cp==32||r.cp==133||r.cp==8206||r.cp==8207||r.cp==8232||r.cp==8233;if(syntax||white)out.push_back(92);out+=utf8_cp(r.cp);}return out;}
std::string serialize(const Tailoring&t){std::string out;for(const auto&r:t.rules){if(r.op==1){out+='&';if(r.before)out+="[before "+std::to_string(r.before)+"]";out+=r.text.starts_with('[')?r.text:encoded(r.text);}else if(r.op==2){out+=r.strength?std::string(r.strength,'<'):"=";if(r.starred)out+='*';if(!r.prefix.empty())out+=encoded(r.prefix)+"|";out+=encoded(r.text,r.starred);if(!r.extension.empty())out+="/"+encoded(r.extension);}else if(r.op==3||r.op==4)out+="["+r.text+"]";else bad("AST opcode");out+='\n';}return out;}
std::vector<UChar> utf16(const std::string&s){UErrorCode e=U_ZERO_ERROR;int32_t n=0;u_strFromUTF8(nullptr,0,&n,s.data(),s.size(),&e);if(e!=U_BUFFER_OVERFLOW_ERROR&&U_FAILURE(e))bad("UTF16 sizing");e=U_ZERO_ERROR;std::vector<UChar> out(n);u_strFromUTF8(out.data(),n,&n,s.data(),s.size(),&e);if(U_FAILURE(e))bad("UTF16");return out;}
std::vector<UChar> utf16_runes(const std::string&s){std::vector<UChar> out;for(auto r:decode(s)){if(r.cp<=0xFFFF)out.push_back(r.cp);else{out.push_back(0xD800+((r.cp-0x10000)>>10));out.push_back(0xDC00+((r.cp-0x10000)&1023));}}return out;}
std::vector<UChar> rules_utf16(const std::string&s){auto input=utf16(s);std::vector<UChar> out;for(std::size_t i=0;i<input.size();){auto c=input[i++];if(c!=92||i==input.size()){out.push_back(c);continue;}auto kind=input[i++];if(kind==92){out.push_back(92);continue;}if(kind!=117&&kind!=85){out.push_back(c);out.push_back(kind);continue;}int n=kind==117?4:8;std::uint32_t cp=0;for(int j=0;j<n;++j){if(i==input.size())bad("source Unicode escape EOF");auto h=input[i++];int v=h>=48&&h<=57?h-48:h>=65&&h<=70?h-55:h>=97&&h<=102?h-87:-1;if(v<0)bad("source Unicode escape");cp=(cp<<4)|v;}if(cp>0x10FFFF)bad("source escape range");if(cp<=0xFFFF)out.push_back(cp);else{out.push_back(0xD800+((cp-0x10000)>>10));out.push_back(0xDC00+((cp-0x10000)&1023));}}return out;}
UCollator* compile(const std::string&s,const std::string&name,bool source_xml){auto text=source_xml?rules_utf16(s):utf16(s);UErrorCode e=U_ZERO_ERROR;UParseError parse{};auto c=ucol_openRules(text.empty()?u"":text.data(),text.size(),UCOL_DEFAULT,static_cast<UCollationStrength>(UCOL_DEFAULT),&parse,&e);if(U_FAILURE(e)){std::cerr<<"PARSE_CONTEXT ";for(std::size_t i=static_cast<std::size_t>(std::max(0,parse.offset-40));i<text.size()&&i<static_cast<std::size_t>(parse.offset+40);++i)std::cerr<<std::hex<<static_cast<std::uint32_t>(text[i])<<",";std::cerr<<"\\n";bad("ICU rules "+name+": "+u_errorName(e)+" line="+std::to_string(parse.line)+" offset="+std::to_string(parse.offset));}return c;}
std::vector<std::uint8_t> key(UCollator*c,const std::vector<UChar>&s){auto n=ucol_getSortKey(c,s.empty()?u"":s.data(),s.size(),nullptr,0);if(n<1)bad("sortkey sizing");std::vector<std::uint8_t> out(n);if(ucol_getSortKey(c,s.empty()?u"":s.data(),s.size(),out.data(),n)!=n)bad("sortkey");return out;}
int main(int argc,char**argv){try{if(argc!=2)return 64;controls();std::vector<fs::path> files;for(const auto&e:fs::directory_iterator(fs::path(argv[1])/"common/collation"))if(e.path().extension()==".xml")files.push_back(e.path());std::sort(files.begin(),files.end());std::uint64_t tailorings=0,probes=0;for(const auto&p:files)for(const auto&t:xml(p)){
 auto name=t.locale+"/"+t.type+"/"+t.variant;std::ofstream("current-original.rules")<<t.source_rules;std::ofstream("current-ast.rules")<<serialize(t);auto before=compile(t.source_rules,name+" original",true),after=compile(serialize(t),name+" AST",false);
 std::vector<std::vector<UChar>> samples={{},{0},{0x61},{0x41},{0x61,0x301},{0xE9},{0x65,0x301},{0xFFFE},{0xFFFF},{0xD83D,0xDE00}};
 for(const auto&r:t.rules){if(r.op!=2)continue;auto text=utf16_runes(r.prefix+r.text);samples.push_back(text);if(!r.extension.empty())samples.push_back(utf16_runes(r.extension));for(auto cp:decode(r.text)){std::vector<UChar> single;if(cp.cp<=0xFFFF)single.push_back(cp.cp);else{single.push_back(0xD800+((cp.cp-0x10000)>>10));single.push_back(0xDC00+((cp.cp-0x10000)&1023));}samples.push_back(std::move(single));}}
 for(const auto&sample:samples){if(key(before,sample)!=key(after,sample)){std::ofstream("failed-original.rules")<<t.source_rules;std::ofstream("failed-ast.rules")<<serialize(t);std::cerr<<"PROBE ";for(auto cp:sample)std::cerr<<std::hex<<static_cast<std::uint32_t>(cp)<<",";std::cerr<<" BEFORE ";for(auto b:key(before,sample))std::cerr<<std::hex<<static_cast<int>(b)<<",";std::cerr<<" AFTER ";for(auto b:key(after,sample))std::cerr<<std::hex<<static_cast<int>(b)<<",";std::cerr<<"\\n";bad("AST changed sortkey "+name);}++probes;}
 ucol_close(before);ucol_close(after);++tailorings;std::cout<<"CLDR_AST_LOCALE_OK "<<name<<" probes="<<samples.size()<<'\n';
 }
 if(!tailorings||!probes)bad("empty AST oracle");std::cout<<"CLDR_AST_ORACLE_OK tailorings="<<tailorings<<" probes="<<probes<<"\n";return 0;
}catch(const std::exception&e){std::cerr<<"CLDR_AST_ORACLE_ERROR "<<e.what()<<"\n";return 1;}}
